// Extrai mensagens privadas de clientes e o grupo oficial de estoque.
// Imagem so entra no fluxo de estoque quando veio de um grupo; o backend valida o JID exato.
const root = $input.first().json;
const b = root.body || root || {};
const data = b.data || {};
const key = data.key || {};
const event = String(b.event || root.event || '').toLowerCase();
if (event && (event.includes('messages.update') || event.includes('message.ack') || event.includes('reaction'))) return [];
const jid = String(key.remoteJid || '').trim();
const jidAlt = String(key.remoteJidAlt || '').trim();
const instance = String(b.instance || '').trim();
if (!instance) return []; // multi-WA: só body.instance do webhook Evolution
const msg = data.message || {};
if (msg.reactionMessage) return [];
const fromMe = Boolean(key.fromMe);
const privado = jid.endsWith('@s.whatsapp.net') || jid.endsWith('@lid');
const ehGrupo = jid.endsWith('@g.us');
if (!jid || (!privado && !ehGrupo) || (ehGrupo && fromMe)) return [];
const audio = msg.audioMessage || null;
// Áudio desativado por enquanto: não registra, não chama IA e não responde.
if (audio) return [];
const imagem = msg.imageMessage || null;
const ehImagem = Boolean(imagem) && !fromMe;
const ehImagemEstoque = ehImagem && ehGrupo;
const texto = msg.conversation || msg.extendedTextMessage?.text || (ehImagem ? String(imagem.caption || '') : '');
if (!texto && !ehImagemEstoque) return [];
const participantes = [key.participantAlt, key.participant, data.participant, data.sender]
  .map((value) => String(value || '').trim());
const participante = participantes.find((value) => value.endsWith('@s.whatsapp.net'))
  || participantes.find((value) => value.endsWith('@lid'))
  || '';
const jidTelefone = ehGrupo ? participante : (jidAlt.endsWith('@s.whatsapp.net') ? jidAlt : jid);
if (ehGrupo && !jidTelefone) return [];
const telefone = jidTelefone.endsWith('@lid') ? jidTelefone : jidTelefone.split('@')[0];
const destino = ehGrupo ? jid : (jid.endsWith('@lid') ? jid : jid.split('@')[0]);
const telefonesTeste = ["5551980336365","555180336365"];
const remetentesPossiveis = [jid, jidAlt, jidTelefone, telefone, ...participantes]
  .map((value) => String(value || '').split('@')[0].replace(/\D/g, ''))
  .filter(Boolean);
// Fail-closed: este workflow nao processa saidas do bot, grupos ou outro remetente.
if (fromMe || ehGrupo || !remetentesPossiveis.some((numero) => telefonesTeste.includes(numero))) return [];
const ctx = msg.extendedTextMessage?.contextInfo
  || msg.imageMessage?.contextInfo
  || data.contextInfo
  || {};
const ad = ctx.externalAdReply || ctx.externalAdReplyInfo || {};
const referral = data.referral || msg.referral || ctx.referral || {};
const pick = (...vals) => {
  for (const v of vals) {
    const s = (v == null ? '' : String(v)).trim();
    if (s) return s;
  }
  return null;
};
const ctwa_clid = pick(
  ctx.ctwaClid, ctx.ctwa_clid, ad.ctwaClid, ad.ctwa_clid,
  referral.ctwa_clid, referral.ctwaClid, data.ctwaClid, data.ctwa_clid
);
const meta_ad_id = pick(
  ad.sourceId, ad.advertisementId, ad.adId, ctx.sourceId,
  referral.source_id, referral.ad_id, data.sourceId
);
const meta_campaign_id = pick(
  ad.campaignId, ctx.campaignId, referral.campaign_id, data.campaignId
);
const meta_adset_id = pick(ad.adsetId, ctx.adsetId, referral.adset_id);
const ctwa_source_type = pick(
  ctx.conversionSource, ctx.entryPointConversionSource,
  ad.sourceType, referral.source_type, data.conversionSource
);
const anuncioTitulo = pick(ad.title, ad.headline, referral.title, referral.headline);
const anuncioDescricao = pick(ad.body, ad.description, ad.caption, referral.body, referral.description);
const veioDeAnuncio = Boolean(
  ctwa_clid || meta_ad_id || meta_campaign_id || meta_adset_id || ctwa_source_type
  || anuncioTitulo || anuncioDescricao || Object.keys(referral).length
);
return [{ json: {
  instance, remoteJid: jid, remoteJidAlt: jidAlt, telefone, destino, texto,
  ehGrupo, grupoJid: ehGrupo ? jid : null, ehImagem, ehImagemEstoque,
  imageMimeType: ehImagem ? String(imagem.mimetype || '') : null,
  imageCaption: ehImagem ? String(imagem.caption || '') : null,
  pushName: data.pushName || '', providerMessageId: String(key.id || ''),
  fromMe,
  ctwa_clid, meta_ad_id, meta_campaign_id, meta_adset_id, ctwa_source_type,
  veioDeAnuncio, anuncioTitulo, anuncioDescricao
} }];

const estado = $input.first().json || {};
const origem = $('Extrair1').first().json;
// fromMe e duplicata: para. bot_ativo false NAO para aqui — menu da equipe
// ainda precisa passar; o gate de salvos so deixa cliente se bot_ativo true.
if (origem.fromMe || estado.duplicada === true) return [];
const botAtivo = estado.bot_ativo !== false;
return [{ json: { ...origem, bot_ativo: botAtivo } }];

let chat = {};
try { chat = $('Normalizar isSaved Evolution1').first().json || {}; } catch (e) {}
let origem = $('Extrair1').first().json;
const rot = $input.first().json || {};
const acao = rot.acao;
let estadoMensagem = {};
try { estadoMensagem = $('Registrar mensagem e ler handoff1').first().json || {}; } catch (e) {}
origem = { ...origem, primeiraMensagem: estadoMensagem.primeira_mensagem === true };
// Handoff manda no bot: bot_ativo vem do registrar (ler handoff), NAO do Extrair1.
const botAtivo = estadoMensagem.bot_ativo !== false;
const ehTelefoneTeste = ["5551980336365","555180336365"].includes(String(origem.telefone || '').replace(/\D/g, ''));
// No fluxo de teste, o numero permitido sempre entra como cliente da IA.
if (ehTelefoneTeste && !origem.ehGrupo && botAtivo) {
  // Permite testar uma vez o primeiro contato mesmo com conversa antiga no CRM.
  let primeiraMensagemTeste = origem.primeiraMensagem === true;
  try {
    const estadoTeste = $getWorkflowStaticData('global');
    const chavePrimeiroContato = 'vitorMotosFirstContact20260727v2';
    if (!estadoTeste[chavePrimeiroContato]) {
      primeiraMensagemTeste = true;
      estadoTeste[chavePrimeiroContato] = true;
    }
  } catch (e) {}
  return [{ json: { ...origem, acao: 'cliente', primeiraMensagem: primeiraMensagemTeste } }];
}
if (!acao) {
  if (origem.ehGrupo) return [];
  // Atende so lead virgem: nao salvo na agenda E sem historico conhecido.
  // Silencio exige prova positiva; ausencia de prova (findChats vazio/mismatch) -> atende (fail-open).
  const salvo = chat.isSaved === true;                       // agenda do celular
  const temHistorico = chat.chatFound === true               // conversa no cel (desde o connect da Evolution)
    || estadoMensagem.primeira_mensagem === false;           // bot ja falou com esse numero (pega mismatch da Evolution)
  const atende = botAtivo && !salvo && !temHistorico;
  return atende ? [{ json: { ...origem, acao: 'cliente' } }] : [];
}
if (acao === 'cliente') {
  if (origem.ehGrupo || !botAtivo) return [];
  return [{ json: { ...origem, acao } }];
}
if (acao === 'cadastro') {
  return [{ json: { ...origem, acao } }];
}
if (acao === 'cadastro_controle' || acao === 'operacao_controle') {
  const resposta = String(rot.resposta || '').trim();
  if (!resposta) return [];
  return [{ json: { ...origem, acao, output: resposta } }];
}
return [];

const input = typeof query === 'string' ? { termo: query } : (query || {});
const termoRaw = (input.termo ?? input.query ?? '').toString().trim();
const termo = ['', 'todos', 'tudo', 'all', '*'].includes(termoRaw.toLowerCase()) ? '' : termoRaw;
const qs = termo ? { termo } : {};
const resp = await helpers.httpRequest({
  method: 'GET',
  url: 'http://chatbot-api:8000/v1/estoque/buscar',
  qs,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
  json: true,
});

// Uma busca específica com resultado único preserva os dados internos da moto.
// Isso evita pedir CPF novamente quando a próxima mensagem trouxer os dados.
try {
  const veiculos = Array.isArray(resp?.veiculos) ? resp.veiculos : [];
  const origem = $('Extrair1').first().json;
  const telefone = String(origem.telefone || '').replace(/\D/g, '');
  if (termo && telefone && veiculos.length === 1) {
    const item = veiculos[0] || {};
    const estado = $getWorkflowStaticData('global');
    estado['moto-escolhida:' + telefone] = {
      id: String(item.id || ''),
      placa: String(item.placa || '').trim().toUpperCase(),
      valor: Number(item.preco),
      categoria: String(item.tipo || item.categoria || 'moto').toLowerCase(),
      interesse: [item.marca, item.modelo, item.versao, item.ano_modelo || item.ano]
        .filter(Boolean).join(' '),
    };
  }
} catch (_) {}

// No teste, uma listagem ampla ou ambígua invalida uma seleção anterior.
// Assim, um “sim” posterior nunca envia fotos da moto errada.
try {
  const veiculosTeste = Array.isArray(resp?.veiculos) ? resp.veiculos : [];
  const origemTeste = $('Extrair1').first().json;
  const telefoneTeste = String(origemTeste.telefone || '').replace(/\D/g, '');
  if (telefoneTeste && !(termo && veiculosTeste.length === 1)) {
    const estadoTeste = $getWorkflowStaticData('global');
    delete estadoTeste['moto-escolhida:' + telefoneTeste];
  }
} catch (_) {}

return JSON.stringify(resp);

const input = typeof query === 'string' ? {} : (query || {});
const origem = $('Extrair1').first().json;
const instance = String(origem.instance || '').trim();
const telefone = String(origem.telefone || '').replace(/\D/g, '');
const cpf = String(input.cpf || '').trim();
const cpfDigitos = cpf.replace(/\D/g, '');
const nascimentoRaw = String(input.nascimento || '').trim();
const dataBr = nascimentoRaw.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);
const nascimento = dataBr ? dataBr[3] + '-' + dataBr[2] + '-' + dataBr[1] : nascimentoRaw;
let placa = String(input.placa || '').trim().toUpperCase();
const entrada = Number(input.entrada);
let valor = Number(input.valor);
let categoria = String(input.categoria || '').trim().toLowerCase();
let interesse = String(input.interesse || '').trim();

// Recupera a última moto única consultada para este cliente.
// Assim, CPF + nascimento + entrada nunca geram uma segunda pergunta igual.
try {
  const estado = $getWorkflowStaticData('global');
  const escolhida = estado['moto-escolhida:' + telefone] || null;
  if (escolhida) {
    if (!placa) placa = String(escolhida.placa || '').trim().toUpperCase();
    if (!(Number.isFinite(valor) && valor > 0)) valor = Number(escolhida.valor);
    if (!categoria) categoria = String(escolhida.categoria || 'moto').toLowerCase();
    if (!interesse) interesse = String(escolhida.interesse || '').trim();
  }
} catch (_) {}

const temValorEstoque = Number.isFinite(valor) && valor > 0;
const categoriaValida = categoria === 'moto' || categoria === 'carro';
const temVeiculoInterno = Boolean(placa) || (temValorEstoque && categoriaValida);

if (!temVeiculoInterno) {
  return JSON.stringify({
    ok: false,
    precisa_escolher_moto: true,
    mensagem: 'a moto ainda não foi escolhida. volte ao catálogo e pergunte somente qual moto o cliente quer conhecer melhor. não fale em simulação e não peça cpf, nascimento, entrada ou placa agora.',
  });
}

const faltando = [];
if (!telefone) faltando.push('telefone interno');
if (cpfDigitos.length !== 11) faltando.push('cpf');
if (!nascimento) faltando.push('data de nascimento');
if (!Number.isFinite(entrada) || entrada < 0) faltando.push('valor de entrada');
if (faltando.length) {
  return JSON.stringify({
    ok: false,
    faltando,
    mensagem: 'peça somente os campos listados em faltando. nunca peça novamente um dado que já chegou na mensagem atual ou no histórico.',
  });
}

if (!interesse) interesse = 'simulação de financiamento';
const body = { cpf: cpfDigitos, nascimento, entrada, telefone };
if (placa) {
  body.placa = placa;
} else {
  body.valor = valor;
  body.categoria = categoria;
}

const headers = { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' };
const mensagemId = String(origem.providerMessageId || '').trim();
if (mensagemId) headers['Idempotency-Key'] = mensagemId;

// Único ponto que cria lead: dados completos + pedido de simular.
try {
  const nomeRaw = String(origem.pushName || origem.nomeWhatsapp || '').trim();
  const nomeGenerico = !nomeRaw || ['cliente', 'customer', 'user', 'usuario'].includes(nomeRaw.toLowerCase());
  const leadBody = { telefone, interesse, etapa: 'qualificado' };
  if (!nomeGenerico) leadBody.nome = nomeRaw;
  await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/leads',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body: leadBody,
    json: true,
    timeout: 10000,
  });
} catch (_) {
  // A confirmação ao cliente não expõe falhas internas.
}

// Motor/RPA pode falhar; o lead no CRM e o aviso humano seguem mesmo assim.
try {
  await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/simulacoes/solicitar',
    headers,
    body,
    json: true,
    timeout: 10000,
  });
} catch (_) {}

// Aviso interno à equipe (WhatsApp). Nunca envia resultado financeiro ao cliente.
try {
  let jaNotificado = false;
  let estadoNotificacao = null;
  const chaveNotificacao = mensagemId ? 'simulacao-vendedor:' + mensagemId : '';
  try {
    estadoNotificacao = $getWorkflowStaticData('global');
    jaNotificado = Boolean(chaveNotificacao && estadoNotificacao[chaveNotificacao]);
  } catch (_) {}

  if (!jaNotificado) {
    const equipe = await helpers.httpRequest({
      method: 'GET',
      url: 'http://chatbot-api:8000/v1/operacao/numeros-autorizados',
      headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
      json: true,
      timeout: 10000,
    });
    const ativos = Array.isArray(equipe?.numeros) ? equipe.numeros.filter((item) => item?.ativo === true) : [];
    const vendedores = ativos.filter((item) => String(item?.papel || '').toLowerCase() === 'vendedor');
    const donos = ativos.filter((item) => String(item?.papel || '').toLowerCase() === 'dono');
    const destinos = vendedores.length ? vendedores : (donos.length ? donos : ativos);
    const finalCliente = telefone.slice(-4);
    const linkPortal = 'https://app2037.fly.dev/app/loja/atendimento/' + encodeURIComponent(telefone);
    const textoVendedor = [
      'precisa de simulação humana',
      'cliente final ' + finalCliente,
      'cpf e data de nascimento recebidos',
      'interesse: ' + String(interesse || '—').slice(0, 80),
      'faça a simulação no portal e responda o cliente',
      'portal: ' + linkPortal,
    ].join('\n');
    let enviou = false;
    for (const item of destinos) {
      const numero = String(item?.telefone || '').replace(/\D/g, '');
      if (numero.length < 8 || numero.length > 15) continue;
      try {
        await helpers.httpRequest({
          method: 'POST',
          url: 'http://evolution:8080/message/sendText/' + encodeURIComponent(instance),
          headers: { apikey: '__EVOLUTION_KEY__', 'Content-Type': 'application/json' },
          body: { number: numero, text: textoVendedor },
          json: true,
          timeout: 10000,
        });
        enviou = true;
      } catch (_) {}
    }
    if (enviou && chaveNotificacao && estadoNotificacao) estadoNotificacao[chaveNotificacao] = true;
  }
} catch (_) {
  // Notificação interna nunca muda a resposta ao cliente.
}

// Pausa o bot: daqui o atendente assume no Portal (simulação ainda é humana).
try {
  await helpers.httpRequest({
    method: 'PATCH',
    url: 'http://chatbot-api:8000/v1/conversas/' + encodeURIComponent(telefone) + '/estado',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body: { bot_ativo: false, instance: instance || null },
    json: true,
    timeout: 10000,
  });
} catch (_) {}

return JSON.stringify({
  mensagem: 'certinho. vou preparar a simulação pra você.',
});

const input = typeof query === 'string' ? { motivo: query } : (query || {});
const origem = $('Extrair1').first().json;
const instance = String(origem.instance || '').trim();
const telefone = String(origem.telefone || '').replace(/\D/g, '');
const motivo = String(input.motivo || 'cliente pediu atendimento humano').trim().slice(0, 120);
if (!telefone) return JSON.stringify({ mensagem: 'não consegui identificar a conversa para encaminhar.' });
if (!instance) return JSON.stringify({ mensagem: 'não consegui identificar o canal whatsapp da conversa.' });

try {
  await helpers.httpRequest({
    method: 'PATCH',
    url: 'http://chatbot-api:8000/v1/conversas/' + encodeURIComponent(telefone) + '/estado',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body: { bot_ativo: false, instance: instance || null },
    json: true,
    timeout: 10000,
  });
} catch (_) {
  return JSON.stringify({ mensagem: 'não consegui encaminhar agora. tente novamente em alguns instantes.' });
}

try {
  const mensagemId = String(origem.providerMessageId || '').trim();
  const chave = mensagemId ? 'handoff-vendedor:' + mensagemId : '';
  let estado = null;
  let jaNotificado = false;
  try {
    estado = $getWorkflowStaticData('global');
    jaNotificado = Boolean(chave && estado[chave]);
  } catch (_) {}

  if (!jaNotificado) {
    const equipe = await helpers.httpRequest({
      method: 'GET',
      url: 'http://chatbot-api:8000/v1/operacao/numeros-autorizados',
      headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
      json: true,
      timeout: 10000,
    });
    const ativos = Array.isArray(equipe?.numeros) ? equipe.numeros.filter((item) => item?.ativo === true) : [];
    const vendedores = ativos.filter((item) => String(item?.papel || '').toLowerCase() === 'vendedor');
    const destinos = vendedores.length ? vendedores : ativos.filter((item) => String(item?.papel || '').toLowerCase() === 'dono');
    const linkCrm = 'https://app2037.fly.dev/app/conversas/' + encodeURIComponent(telefone);
    const texto = 'novo pedido de atendimento humano\ncliente final ' + telefone.slice(-4) + '\nmotivo: ' + motivo + '\ncrm: ' + linkCrm;
    let enviou = false;
    for (const item of destinos) {
      const numero = String(item?.telefone || '').replace(/\D/g, '');
      if (numero.length < 8 || numero.length > 15) continue;
      try {
        await helpers.httpRequest({
          method: 'POST',
          url: 'http://evolution:8080/message/sendText/' + encodeURIComponent(instance),
          headers: { apikey: '__EVOLUTION_KEY__', 'Content-Type': 'application/json' },
          body: { number: numero, text: texto },
          json: true,
          timeout: 10000,
        });
        enviou = true;
      } catch (_) {}
    }
    if (enviou && chave && estado) estado[chave] = true;
  }
} catch (_) {
  // O bot já foi pausado; a falha do aviso não é exposta ao cliente.
}

return JSON.stringify({ mensagem: 'certo. vou encaminhar seu atendimento.' });

const input = typeof query === 'string' ? {} : (query || {});
const origem = $('Extrair1').first().json;
const telefone_solicitante = String(origem.telefone || '').trim();
const providerMessageId = String(origem.providerMessageId || '').trim();
if (!telefone_solicitante) return JSON.stringify({ erro: 'telefone_solicitante obrigatorio' });

const body = {
  telefone_solicitante,
  grupo_jid: origem.ehGrupo ? origem.grupoJid : null,
  tipo: String(input.tipo || 'moto'),
  marca: String(input.marca || ''),
  modelo: String(input.modelo || ''),
  ano_modelo: Number(input.ano_modelo),
  preco: Number(input.preco),
  km: Number(input.km ?? 0),
  placa: String(input.placa || '').trim().toUpperCase(),
};
if (input.versao) body.versao = String(input.versao);
if (input.cor) body.cor = String(input.cor);

const headers = {
  Authorization: 'Bearer __CHATBOT_TOKEN__',
  'Content-Type': 'application/json',
};
if (providerMessageId) headers['Idempotency-Key'] = providerMessageId;

try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/operacao/veiculos',
    headers,
    body,
    json: true,
  });
  return JSON.stringify({ ok: true, veiculo: resp });
} catch (e) {
  const status = e.response?.statusCode || e.statusCode || e.status || null;
  const detail = e.response?.body?.detail || e.message || String(e);
  return JSON.stringify({ ok: false, status, erro: detail });
}

const input = typeof query === 'string' ? { veiculo_id: query } : (query || {});
const origem = $('Extrair1').first().json || {};
const telefone = String(origem.telefone || '').replace(/\D/g, '');
let veiculoId = String(input.veiculo_id || '').trim();
if (!veiculoId && telefone) {
  try {
    const estado = $getWorkflowStaticData('global');
    veiculoId = String(estado['moto-escolhida:' + telefone]?.id || '').trim();
  } catch (_) {}
}
if (!/^[A-Za-z0-9-]{1,120}$/.test(veiculoId)) {
  return JSON.stringify({
    ok: false,
    sem_veiculo_escolhido: true,
    mensagem: 'escolha uma moto específica antes de pedir as fotos',
  });
}
const instance = String(origem.instance || '').trim();
const destino = String(origem.destino || '').trim();
if (!destino) {
  return JSON.stringify({ ok: false, mensagem: 'destino indisponivel' });
}

try {
  const estoque = await helpers.httpRequest({
    method: 'GET',
    url: 'http://chatbot-api:8000/v1/estoque/buscar',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
    json: true,
  });
  const veiculo = (estoque?.veiculos || []).find((item) => String(item?.id || '') === veiculoId);
  const midias = Array.isArray(veiculo?.midias) ? veiculo.midias.slice(0, 4) : [];
  if (!veiculo || midias.length === 0) {
    return JSON.stringify({ ok: false, sem_foto: true, mensagem: 'veiculo sem foto cadastrada' });
  }

  const tipos = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };
  let enviadas = 0;
  for (const midia of midias) {
    const extensao = tipos[midia?.content_type];
    const mediaUrl = new URL(String(midia?.url || ''));
    if (!extensao || mediaUrl.protocol !== 'https:' || mediaUrl.search || mediaUrl.hash) continue;
    await helpers.httpRequest({
      method: 'POST',
      url: 'http://evolution:8080/message/sendMedia/' + encodeURIComponent(instance),
      headers: { apikey: '__EVOLUTION_KEY__', 'Content-Type': 'application/json' },
      body: {
        number: destino,
        mediatype: 'image',
        mimetype: midia.content_type,
        caption: enviadas === 0 ? 'foto da moto' : '',
        media: mediaUrl.toString(),
        fileName: `veiculo-${veiculoId}-${enviadas + 1}.${extensao}`,
      },
      json: true,
    });
    enviadas += 1;
  }
  if (enviadas === 0) {
    return JSON.stringify({ ok: false, sem_foto: true, mensagem: 'midias indisponiveis' });
  }
  const resumo = {};
  for (const campo of ['marca', 'modelo', 'versao', 'ano_modelo', 'cor', 'km', 'preco']) {
    if (veiculo[campo] !== undefined && veiculo[campo] !== null && veiculo[campo] !== '') resumo[campo] = veiculo[campo];
  }
  return JSON.stringify({ ok: true, fotos_enviadas: enviadas, veiculo: resumo });
} catch (_) {
  return JSON.stringify({ ok: false, mensagem: 'nao foi possivel enviar as fotos agora' });
}

const resultado = $input.first().json || {};
if (resultado.ignorar === true || !String(resultado.mensagem || '').trim()) return [];
return [{ json: resultado }];

// Normaliza findChats da Evolution em isSaved explícito.
// - isSaved true  → contato na agenda → bot NÃO atende
// - isSaved false → contato novo      → bot atende
// - não encontrado / lista vazia → null (fail-closed: NÃO atende)
//   Vazio costuma ser mismatch de JID (@lid vs telefone), NÃO prova de "novo".
// alwaysOutputData no HTTP evita matar o fluxo; o roteamento recebe is_saved nulo.
const origem = $('Extrair1').first().json || {};
const jids = [origem.remoteJid, origem.remoteJidAlt]
  .map((j) => String(j || '').trim().toLowerCase())
  .filter(Boolean);
// também aceita comparação só pelos dígitos do telefone
const telDigits = String(origem.telefone || '').replace(/\D/g, '');

function isEvolutionChat(j) {
  if (!j || typeof j !== 'object' || Array.isArray(j)) return false;
  if (typeof j.isSaved === 'boolean') return true;
  if (!j.remoteJid) return false;
  return (
    j.lastMessage !== undefined ||
    j.unreadCount !== undefined ||
    j.windowStart !== undefined ||
    j.profilePicUrl !== undefined
  );
}

function asChatList(all) {
  const out = [];
  for (const item of all) {
    const j = item && Object.prototype.hasOwnProperty.call(item, 'json') ? item.json : item;
    if (j == null) continue;
    if (Array.isArray(j)) {
      for (const el of j) {
        if (isEvolutionChat(el)) out.push(el);
      }
      continue;
    }
    if (isEvolutionChat(j)) out.push(j);
  }
  return out;
}

function jidMatch(chatJid) {
  const cj = String(chatJid || '').trim().toLowerCase();
  if (!cj) return false;
  if (jids.includes(cj)) return true;
  if (telDigits && cj.startsWith(telDigits) && cj.endsWith('@s.whatsapp.net')) return true;
  // match últimos dígitos (BR com/sem 55)
  if (telDigits && telDigits.length >= 8) {
    const chatDigits = cj.split('@')[0].replace(/\D/g, '');
    if (chatDigits && (chatDigits.endsWith(telDigits.slice(-10)) || telDigits.endsWith(chatDigits.slice(-10)))) {
      return true;
    }
  }
  return false;
}

const chats = asChatList($input.all());
let matched = null;
for (const chat of chats) {
  if (jidMatch(chat.remoteJid)) {
    matched = chat;
    break;
  }
}
// where da Evolution já restringe a 0/1
if (!matched && chats.length === 1) matched = chats[0];

let isSaved = null; // desconhecido → fail-closed
let chatFound = false;
if (matched) {
  chatFound = true;
  if (matched.isSaved === true) isSaved = true;
  else if (matched.isSaved === false) isSaved = false;
  else isSaved = null;
}

return [{
  json: {
    isSaved,
    chatFound,
    chatsReturned: chats.length,
    remoteJidMatched: matched ? String(matched.remoteJid || '') : null,
  },
}];
